// How a middleware (compress.ts:126, pretty-json.ts:64) builds the new response:
const oldRes = new Response("old", { headers: [] })
oldRes.headers.append("set-cookie","a=1; Path=/")
oldRes.headers.append("set-cookie","b=2; Path=/")
const newRes = new Response(oldRes.body, oldRes) // exactly what compress/pretty-json do
console.log("new res already contains old cookies:", newRes.headers.getSetCookie())
// naive "merge old + new" would append them again:
const naive = new Response(newRes.body, newRes)
for (const ck of oldRes.headers.getSetCookie()) naive.headers.append("set-cookie", ck)
console.log("naive old+new merge =>", naive.headers.getSetCookie(), "<-- DUPLICATED")
'

